export function resolvePalette(keys, lookup) {
  const pending = new Array(keys.length);

  for (let index = 0; index < keys.length; index += 1) {
    try {
      pending[index] = Promise.resolve(lookup(keys[index]));
    } catch (reason) {
      pending[index] = Promise.reject(reason);
    }
  }

  return Promise.all(pending);
}
